var t=`1123-macaroni-and-cheese`;var i=`world-1123`;var n=`US`;var o=`northern-america`;var r=8;var s=46;var l={en:`Macaroni and Cheese`,ua:`Макарони з сиром`};var u={en:`Macaroni and Cheese is a dish from United States prepared with macaroni, all-purpose flour, whole cow milk, cheddar cheese. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Макарони з сиром, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: макарони, пшеничне борошно універсальне, цільне коров'яче молоко, сир чедер. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Cook the pasta in generously salted boiling water for about 9 minutes until al dente; reserve a cup of its starchy water.`,ua:`Варіть пасту в добре підсоленій киплячій воді приблизно 9 хвилин до стану аль денте; збережіть чашку крохмалистої води.`,t:[`pasta-boiling`],m:9,i:[[`macaroni`,440,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 10 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 10 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:10,i:[[`unsalted-butter`,70,`g`],[`all-purpose-flour`,65,`g`],[`whole-cow-milk`,850,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`cheddar-cheese`,460,`g`],[`ground-mustard`,5,`g`],[`table-salt`,null,`to_taste`]]},{en:`Bake in a preheated 180°C oven for about 20 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 20 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:20,i:[[`breadcrumbs`,100,`g`],[`unsalted-butter`,25,`g`]]}];var h={slug:t,id:i,country:`US`,region:o,servings:8,minutes:46,title:l,text:u,steps:d};export{n as country,h as default,i as id,s as minutes,o as region,r as servings,t as slug,d as steps,u as text,l as title};